# CSD_RATIONALE_BEGIN
# Strategy: natural-delimiter decoding with explicit span-state tracking.
# Outside spans, decode unconstrained text and allow the model to naturally open
# a << span when it is ready. Inside spans, never call AppendConstrainedStep from
# a completeness branch; instead, if the constrained content is complete, wait
# for the model to naturally emit >> via unconstrained decoding, and only use
# constrained decoding while the span is incomplete but constrainable. Maintain a
# bounded checkpoint only for local recovery from dead constrained continuations.
# Track closed spans and an answer_phase flag so that after at least one closed
# span, or when budget pressure is high, the strategy prefers finishing.
# CSD_RATIONALE_END
in_span = False
answer_phase = False
closed_spans = 0
checkpoint = []
has_checkpoint = False
stall_count = 0

# invariant helpers.lm == lm
# invariant helpers.parser == parser
# invariant lm.ValidTokensIdsLogits()
# invariant 0 <= stepsLeft <= maxSteps
# invariant |generated| + stepsLeft <= maxSteps
# decreases stepsLeft
while stepsLeft > 0:
    if in_span:
        if helpers.EndsWithRightDelimiter(generated):
            in_span = False
            closed_spans += 1
            has_checkpoint = False
            stall_count = 0
            if answer_phase:
                break
        elif helpers.IsComplete(generated):
            prev_len = len(generated)
            generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
            if helpers.EndsWithRightDelimiter(generated):
                in_span = False
                closed_spans += 1
                has_checkpoint = False
                stall_count = 0
                if answer_phase:
                    break
            elif len(generated) == prev_len:
                break
            else:
                stall_count += 1
        elif helpers.CanConstrain(generated):
            if (not has_checkpoint) and helpers.ValidContinuationCount(generated) > 0:
                checkpoint = helpers.Checkpoint(generated)
                has_checkpoint = True
            generated, stepsLeft = helpers.AppendConstrainedStep(prompt, generated, stepsLeft)
            if helpers.EndsWithRightDelimiter(generated):
                in_span = False
                closed_spans += 1
                has_checkpoint = False
                stall_count = 0
                if answer_phase:
                    break
            else:
                if has_checkpoint:
                    generated = helpers.RestoreIfDead(generated, checkpoint)
                stall_count += 1
        else:
            if has_checkpoint:
                generated = helpers.RestoreCheckpoint(checkpoint)
                has_checkpoint = False
            break
    else:
        if helpers.EndsWithLeftDelimiter(generated):
            in_span = True
            has_checkpoint = False
            stall_count = 0
        else:
            if not answer_phase:
                if closed_spans > 0:
                    answer_phase = True
                elif stepsLeft <= 6:
                    answer_phase = True
                elif helpers.MinStepsToComplete(generated) >= stepsLeft:
                    answer_phase = True
                elif stall_count >= 3:
                    answer_phase = True
            prev_len = len(generated)
            generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
            if helpers.EndsWithLeftDelimiter(generated):
                in_span = True
                has_checkpoint = False
                stall_count = 0
            elif len(generated) == prev_len:
                break
            else:
                stall_count += 1

